// Deploy gate: gold + segments + vetoes (plain JS)
function deployGate(baseline, candidate) {
  // {overall, segments: {kind: score}, vetoes: [failed hard gates]}
  if (candidate.vetoes.length) return { ship: false, reason: "veto:" + candidate.vetoes.join(",") };
  for (const [kind, score] of Object.entries(candidate.segments)) {
    if (score < (baseline.segments[kind] ?? 0)) return { ship: false, reason: "regression:" + kind };
  }
  if (candidate.overall <= baseline.overall) return { ship: false, reason: "no-gain" };
  return { ship: true };
}
// Vetoes → segments → gain: same gating order as eval, now blocking deploys.

// Canary verdict: multi-metric with vetoes (plain JS)
function canaryVerdict(base, cand) {
  if (cand.errors > base.errors * 1.1) return { action: "rollback", reason: "error-regression" };
  if (cand.safetyViolations > 0) return { action: "rollback", reason: "safety-veto" };
  for (const seg of Object.keys(base.segments))
    if ((cand.segments[seg] ?? 1) < base.segments[seg]) return { action: "rollback", reason: "segment:" + seg };
  if (cand.quality <= base.quality) return { action: "hold", reason: "no-gain" };
  return { action: "promote" };
}
// Rollback automatic on vetoes; hold (not promote) on flat gains.

